#!/usr/bin/env python3
"""Confirmed semantic Event EBM translation fixes from whole-project review.

These are deliberately record-guarded.  The authority EBM files are binary, so
normal text editing is unsafe; build_final_korean_mod.py applies this list while
rebuilding the installable EBM payloads and refuses to continue if an expected
source translation no longer matches.

Only fixes that were manually checked against the Japanese record and context
belong here.  Broad heuristic audit findings must not be copied into this list
without review.
"""
from __future__ import annotations

from dataclasses import dataclass


