    ("SWC06/EVENT_MESSAGE_SWC06_090.ebm", 38, "그리고, 감정만으로 움직였기에……<CR>당신은 나와 프림을 방치하여,<CR>세상을 파멸로 한 걸음 더 다가서게 했어."),
