    ("SWC08/EVENT_MESSAGE_SWC08_100.ebm", 154, "그리고 지금, 나… 그 이유를 잊어가고 있어.<CR>그건 분명, 프림이 죽었기 때문이야…"),
    ("SWC08/EVENT_MESSAGE_SWC08_110.ebm", 3, "델타, 부탁이야.<CR>내가 프림의 기억을 잃기 전에,<CR>너에게 이 이야기를 들려주고 싶어."),
    ("SWC08/EVENT_MESSAGE_SWC08_110.ebm", 7, "프림이라는 건, 예전 내 친구의<CR>이름이야. 그리고, 델타의 친구이기도 했어."),
