    ("SWC08/EVENT_MESSAGE_SWC08_130.ebm", 45, "하지만 말이야……<CR>할 수 있다면, 프림과도 함께<CR>마지막을 장식하고 싶었어."),
    ("SWC08/EVENT_MESSAGE_SWC08_130.ebm", 53, "프림！！"),
    ("SWC08/EVENT_MESSAGE_SWC08_130.ebm", 58, "씨앗의 힘！<CR>그렇구나…… 호루스가 준 『사랑의 씨앗』이,<CR>프림을 되살려준 것인가！"),
    ("SWC08/EVENT_MESSAGE_SWC08_130.ebm", 59, "프림……<CR>미안해…… 정말 미안해.<CR>나 때문에, 당신을 지워버렸어."),
    ("SWC08/EVENT_MESSAGE_SWC08_130.ebm", 70, "응！<CR>가자, 델타, 프림."),
