    Fix(
        "C32_1/EVENT_MESSAGE_C32_1_030.ebm", 17,
        "그걸 멈추지 않는 건가요！？",
        "그런데 안 말리시는 건가요！？",
    ),
    # とうだいもりよ is a direct address, not a copular statement.
    Fix(
        "C32_1/EVENT_MESSAGE_C32_1_030.ebm", 38,
        "토다이모리로구나……<CR>이놈, 조금 망가진 듯하구나.<CR>내 피로 따위 알 리가 없을 텐데 말이다……",
        "토다이모리여……<CR>이놈, 조금 망가진 듯하구나.<CR>내 피로 따위 알 리가 없을 텐데 말이다……",
    ),
    # 顕在している means manifesting/appearing in this world, not the nonstandard 현재하고.
